#include <cstdio>
#include <vector>
#include <type_traits>

struct Shape {
    virtual double area() const = 0;
    virtual ~Shape() = default;
};
// final：向编译器声明"不再有派生类覆盖"，据此可去虚化/内联
struct Square final : Shape {
    double s;
    explicit Square(double x) : s(x) {}
    double area() const override { return s * s; }
};
struct Circle final : Shape {
    double r;
    explicit Circle(double x) : r(x) {}
    double area() const override { return 3.14159 * r * r; }
};

// 经基类指针调用 → 运行时查虚表（间接分派）
static long g_indirect = 0, g_direct = 0;
double call_indirect(const Shape* p) { ++g_indirect; return p->area(); }
// 静态类型已知且为 final → 编译器可解析到唯一实现（直接分派/内联）
double call_direct(const Square& s)   { ++g_direct;   return s.area(); }

int main() {
    Square sq(2.0);
    Circle ci(1.0);
    std::vector<const Shape*> shapes{&sq, &ci};

    double a1 = 0;
    for (const Shape* p : shapes) a1 += call_indirect(p);
    double a2 = call_direct(sq) + call_direct(sq);

    printf("间接分派调用=%ld 直接调用=%ld\n", g_indirect, g_direct);
    printf("Square is_final=%d Circle is_final=%d\n",
           (int)std::is_final<Square>::value, (int)std::is_final<Circle>::value);
    printf("area(Square)=%g 求和=%g\n", sq.area(), a2);
    (void)a1;
    return 0;
}
